-- Capture this installation's native timezone names and PostgreSQL version together.
SELECT 1,jsonb_agg(name ORDER BY name COLLATE "C"),current_setting('server_version_num')::integer,clock_timestamp()
FROM (SELECT DISTINCT name FROM pg_catalog.pg_timezone_names) AS native_names;
SELECT pg_catalog.setval('public.business_types_id_seq', 6, true);
